+func readSemanticSnapshotSummary(path, repoKey string) (semanticHeader, semanticCounts, error) {
+	f, err := os.Open(path)
+	if err != nil {
+		return semanticHeader{}, semanticCounts{}, err
+	}
+	defer f.Close()
