		if len(fields) < 2 {
			continue
		}
		status := fields[0]
		if (strings.HasPrefix(status, "R") || strings.HasPrefix(status, "C")) && len(fields) >= 3 {
			add(decodeGitPorcelainPath(fields[1]))
			add(decodeGitPorcelainPath(fields[2]))
